import {writeFile} from 'node:fs/promises';import {randomUUID} from 'node:crypto';import path from 'node:path';import {IdentityStore} from '../../src/native/identity-store.ts';import {NativeDispatcher} from '../../src/native/dispatcher.ts';
const root=process.argv[2],point=process.argv[3]||'after_write',now=new Date().toISOString(),i={schemaVersion:1 as const,connectionId:randomUUID(),provider:'codex' as const,targetSessionId:randomUUID(),sourceSessionId:randomUUID(),messageId:randomUUID(),attemptId:randomUUID(),transportId:randomUUID(),wireVersion:'clean-v1' as const,bodySha256:'a'.repeat(64),createdAt:now,updatedAt:now,phase:'prepared' as const};await writeFile(path.join(root,'intent.json'),JSON.stringify(i));await writeFile(path.join(root,'external-write.txt'),'0');const store=new IdentityStore(root,{now:()=>new Date()}),reader:any={inspect:async()=>({status:'missing'})},d=new NativeDispatcher(store,{codex:reader,claude:reader});
if(point==='prepared'||point==='before_write'){await store.prepare(i);if(point==='before_write')await store.advance(i.attemptId,'prepared',{phase:'write_started'});process.exit(17);}
